INSERT INTO settings(key,value) VALUES('profile','{"name":"MD. Tanvir Ahmed Siddique","shortName":"Tanvir Ahmed","headline":"Competitive programmer, CSE graduate and ML enthusiast","description":"MD. Tanvir Ahmed Siddique, CSE graduate and competitive programmer (Codeforces Specialist). Contests, projects and writing.","bio":"I am a competitive programmer and CSE graduate from IUBAT. I have represented my university in 13 onsite programming contests, trained juniors in problem-solving sessions for more than two years, and volunteered as a mentor for the Data Structures and Algorithms course. I currently manage the Programming Club of the IUBAT IT Society.","image":"https://tanvir-005.github.io/Portfolio/images/tanvir.png","imageAlt":"Portrait of MD. Tanvir Ahmed Siddique","institution":"International University of Business Agriculture and Technology (IUBAT)","email":"tanvir.24633@gmail.com","phone":"+88 01704-476935","github":"https://github.com/tanvir-005","linkedin":"https://www.linkedin.com/in/tanvir-ahmed-siddique-/","facebook":"https://www.facebook.com/005tanvir/","codeforces":"twilighTTanvir","footer":"Go where the universe takes..."}') ON CONFLICT(key) DO UPDATE SET value=excluded.value;
