INSERT INTO entries(type,slug,title,summary,body_md,image,date,sort,published,data) VALUES('project','codekoro','CodeKoro','An online code judging system built for the Software Engineering course. It lets people create programming problems and contests, solve problems in a judged environment, take part in contests, and receive verdicts on their solutions.','','','',1,1,'{"subtitle":"An online code judging system","stack":["ASP.NET MVC Core","C#"],"github":"https://github.com/tanvir-005/CodeKoro","live":""}');
INSERT INTO entries(type,slug,title,summary,body_md,image,date,sort,published,data) VALUES('project','linear-algebra-3x3-system-solver','Linear Algebra 3x3 System Solver','A C++ program that implements the logic of solving a system of three linear equations. It reads the system as input, then either calculates the values of the variables or determines whether the system is consistent.','','','',2,1,'{"subtitle":"Linear algebra logic in C++","stack":["C++"],"github":"https://github.com/tanvir-005/LinearAlgebra-SystemSolve_3x3","live":""}');
INSERT INTO entries(type,slug,title,summary,body_md,image,date,sort,published,data) VALUES('project','diabetic-retinopathy-classification','Diabetic Retinopathy Classification','A deep learning approach to determine the severity of diabetic retinopathy from fundus images. The images are preprocessed and a DenseNet121 model is trained to classify them with 96% accuracy. OOP concepts keep the dataset and parameters easy to change.','','','',3,1,'{"subtitle":"Deep learning on fundus images","stack":["Python","TensorFlow","DenseNet121","NumPy","Pandas","Scikit-Learn","Matplotlib","Kaggle"],"github":"https://github.com/tanvir-005/Diabetic-Retinopathy-Detection","live":""}');
INSERT INTO entries(type,slug,title,summary,body_md,image,date,sort,published,data) VALUES('project','spotlight','SpotLight','An event management system for the Visual Programming course, built on the MVC architecture. Organizers can create and manage events, and participants can book them, with authentication and role-based activities.','','','',4,1,'{"subtitle":"Event management system","stack":["C#","ASP.NET","HTML","CSS"],"github":"https://github.com/tanvir-005/SpotLight","live":""}');
INSERT INTO entries(type,slug,title,summary,body_md,image,date,sort,published,data) VALUES('project','library-management-system','Library Management System','A system built for the System Analysis and Design course, applying its principles. It offers librarian functionality together with admin activities.','','','',5,1,'{"subtitle":"Managing the work of a library","stack":["HTML","CSS","PHP","MySQL"],"github":"https://github.com/tanvir-005/library_management","live":""}');
